grid=[[8]*19 for _ in range(10)]
for c in range(15,19): grid[0][c]=3
for c in range(5,9): grid[9][c]=3
for r,c in [(2,7),(3,5),(5,6)]: grid[r][c]=2
# rays from top bar downward, using marker color 2
for r in range(1,10):
    for c in range(15,19): grid[r][c]=2
# rays upward from lower bar, stopping at marker cells, replacing hit by 4
markers={(2,7),(3,5),(5,6)}
for c in range(5,9):
    for r in range(8,-1,-1):
        if (r,c) in markers:
            grid[r][c]=4
            break
        grid[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in grid))
